<?php
declare(strict_types=1);
require_once __DIR__ . '/rewards.php';
require_once __DIR__.'/helpers.php';
function group_transition_map(): array {return ['awaiting_acceptance'=>['accepted','rejected'],'accepted'=>['processing','cancelled'],'processing'=>['quality_check','cancelled'],'quality_check'=>['packing','processing'],'packing'=>['ready_to_dispatch'],'ready_to_dispatch'=>['partially_dispatched','dispatched'],'partially_dispatched'=>['dispatched'],'dispatched'=>['in_transit','delivered','delivery_exception'],'in_transit'=>['delivered','delivery_exception','returned_to_vendor'],'delivery_exception'=>['in_transit','delivered','returned_to_vendor'],'delivered'=>[],'rejected'=>[],'cancelled'=>[],'returned_to_vendor'=>[]];}
function package_transition_map(): array {return ['packing'=>['ready_to_dispatch'],'ready_to_dispatch'=>['dispatched'],'dispatched'=>['picked_up','in_transit','delivered','delivery_attempted'],'picked_up'=>['in_transit','at_destination','delivery_attempted'],'in_transit'=>['at_destination','out_for_delivery','delivery_attempted','delivery_failed','delivered','return_in_transit'],'at_destination'=>['out_for_delivery','delivery_attempted','delivery_failed','delivered','return_in_transit'],'out_for_delivery'=>['delivered','delivery_attempted','delivery_failed'],'delivery_attempted'=>['out_for_delivery','delivery_failed','delivered','return_in_transit'],'delivery_failed'=>['out_for_delivery','return_in_transit'],'return_in_transit'=>['returned_to_vendor'],'delivered'=>[],'returned_to_vendor'=>[]];}
function vendor_group(string $id,string $vendorId,bool $forUpdate=false): array {$stmt=get_db()->prepare('SELECT g.*,o.user_id,o.order_number,o.address_snapshot_json,o.payment_status FROM vendor_order_groups g JOIN orders o ON o.id=g.order_id WHERE g.id=:id AND g.vendor_id=:vendor'.($forUpdate?' FOR UPDATE':''));$stmt->execute(['id'=>$id,'vendor'=>$vendorId]);$row=$stmt->fetch();if(!$row)json_response(404,['success'=>false,'message'=>'Vendor order not found.']);return $row;}
function sync_group_from_packages(string $groupId): void {$db=get_db();$stmt=$db->prepare('SELECT status,COUNT(*) qty FROM shipment_packages WHERE vendor_group_id=:group GROUP BY status');$stmt->execute(['group'=>$groupId]);$statuses=[];foreach($stmt->fetchAll() as $row)$statuses[$row['status']]=(int)$row['qty'];if(!$statuses)return;$next=null;if(count($statuses)===1&&isset($statuses['delivered']))$next='delivered';elseif(count($statuses)===1&&isset($statuses['returned_to_vendor']))$next='returned_to_vendor';elseif(isset($statuses['delivery_failed'])||isset($statuses['delivery_attempted']))$next='delivery_exception';elseif(isset($statuses['in_transit'])||isset($statuses['at_destination'])||isset($statuses['out_for_delivery'])||isset($statuses['picked_up']))$next='in_transit';elseif(isset($statuses['dispatched']))$next=count($statuses)===1?'dispatched':'partially_dispatched';if(!$next)return;$group=$db->prepare('SELECT status,order_id FROM vendor_order_groups WHERE id=:id FOR UPDATE');$group->execute(['id'=>$groupId]);$current=$group->fetch();if(!$current)return;$db->prepare('UPDATE vendor_order_groups SET status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$next,'id'=>$groupId]);$db->prepare('UPDATE order_items SET status=:status WHERE vendor_group_id=:group AND status NOT IN ("cancelled","returned")')->execute(['status'=>$next,'group'=>$groupId]);if($next==='delivered'){$db->prepare('UPDATE vendor_ledger_entries le JOIN order_items oi ON le.reference_type="order_item" AND CAST(le.reference_id AS UNSIGNED)=oi.id SET le.balance_bucket="eligible",le.available_at=UTC_TIMESTAMP() WHERE oi.vendor_group_id=:group AND le.balance_bucket="pending" AND EXISTS (SELECT 1 FROM orders o JOIN vendor_order_groups g2 ON g2.order_id=o.id LEFT JOIN cod_collections c ON c.vendor_group_id=g2.id WHERE g2.id=oi.vendor_group_id AND (o.payment_status="paid" OR c.status="collected"))')->execute(['group'=>$groupId]);}$open=$db->prepare('SELECT COUNT(*) FROM vendor_order_groups WHERE order_id=:order AND status NOT IN ("delivered","cancelled","rejected","returned_to_vendor")');$open->execute(['order'=>$current['order_id']]);if((int)$open->fetchColumn()===0){$failed=$db->prepare('SELECT COUNT(*) FROM vendor_order_groups WHERE order_id=:order AND status<>"delivered"');$failed->execute(['order'=>$current['order_id']]);$orderStatus=(int)$failed->fetchColumn()===0?'delivered':'completed_with_exceptions';$db->prepare('UPDATE orders SET status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:order')->execute(['status'=>$orderStatus,'order'=>$current['order_id']]);if($orderStatus==='delivered'){$db->prepare('UPDATE influencer_conversions SET status="eligible",eligible_at=UTC_TIMESTAMP() WHERE order_id=:order AND status="pending"')->execute(['order'=>$current['order_id']]);$db->prepare('UPDATE influencer_ledger_entries le JOIN influencer_conversions c ON le.reference_type="conversion" AND le.reference_id=c.id SET le.status="eligible" WHERE c.order_id=:order AND le.status="pending"')->execute(['order'=>$current['order_id']]);}}}
